// Scaled for a display in landscape mode. 

// Basic params
var lineCt;
var lineLen; 

function setup() {
	createCanvas(windowWidth, windowHeight);
	lineCt = 40;
	lineLen = windowWidth * 0.1;
}

function makeLine(x, n) {
	// Generates an array of x-values to determine the lines' ends.
	a = [];
	for (let i = 0; i < lineCt; i++) {
		a.push(x + lineLen * cos(n + (frameCount - i) / 123) * sin(n + TWO_PI * i / lineCt - TWO_PI * frameCount / 100));
	}
	return a;
}

function draw() {
	background(0);
	noFill();
	// Generating three arrays storing the x-positions
	arr = makeLine(windowWidth / 2, 0);
	brr = makeLine(windowWidth / 2 - lineLen, 1);
	crr = makeLine(windowWidth / 2 + lineLen, 2);
	stroke(250);
	for (let i = 0; i < lineCt; i++) {
		let y = map(i + 0.5, 0, lineCt - 0.5, 0, height);
		// alternating the left and the right lines
		if (i % 2 == 0) {
			line(arr[i], y, brr[i],y);		
		} else {
			line(arr[i], y, crr[i],y);		
		}
	}	
}
